// The Mailchimp audience fields the guest emails use. Run "Set Up Mailchimp Fields" once to create them.
// Fields that already exist return an error from Mailchimp, which is ignored.
const FIELDS = [
  ['AI_SUBJECT', 'AI subject line'],
  ['AI_PREVIEW', 'AI preview text'],
  ['AI_HEAD', 'AI headline'],
  ['AI_BODY1', 'AI paragraph 1'],
  ['AI_BODY2', 'AI paragraph 2'],
  ['AI_DISHES', 'AI featured dishes'],
  ['AI_CTA', 'AI button text'],
  ['AI_LINK', 'AI button link'],
  ['AI_OFFER', 'AI offer'],
  ['AI_TYPE', 'AI email type'],
  ['AI_SENT', 'AI email sent date'],
];

return FIELDS.map(([tag, name], i) => ({
  json: { tag, name, type: 'text', required: false, public: false, display_order: 50 + i },
}));

// Collects the Square customer id of every guest who placed an order in the history window,
// in batches of 100 for Square's bulk customer lookup.
const ids = new Set();
for (const page of $('Get Square Orders').all()) {
  for (const order of page.json.orders ?? []) {
    if (order.customer_id) ids.add(order.customer_id);
  }
}

const all = [...ids];
const batches = [];
for (let i = 0; i < all.length; i += 100) batches.push(all.slice(i, i + 100));
// Always output one item, so the rest of the run continues even with no known guests
if (!batches.length) batches.push([]);

return batches.map((customer_ids) => ({ json: { customer_ids } }));

// Turns Square orders, customer profiles, and the menu into one guest list:
// each guest's visits, usual days and times, dine-in or takeout, favorite dishes, and average check.
const settings = $('Settings').first().json;

const tzByLocation = new Map((($('Get Square Locations').first().json.locations) ?? []).map((l) => [l.id, l.timezone || settings.timezone]));
const money = (m) => (m && Number.isFinite(Number(m.amount)) ? Number(m.amount) / 100 : 0);
const WEEKDAYS = ['Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday', 'Sunday'];
const daypart = (hour) => (hour >= 5 && hour < 11 ? 'breakfast' : hour >= 11 && hour < 16 ? 'lunch' : hour >= 16 && hour < 22 ? 'dinner' : 'late night');
const orderType = (o) => {
  const t = o.fulfillments?.[0]?.type;
  if (t === 'DELIVERY' || /doordash|uber ?eats|grubhub|postmates/i.test(o.source?.name ?? '')) return 'delivery';
  if (t === 'PICKUP') return 'takeout';
  return 'dine-in';
};

// ---------- Visits (one per guest per day; several orders on one day count as one visit)
const visitsByGuest = new Map();
for (const page of $('Get Square Orders').all()) {
  for (const o of page.json.orders ?? []) {
    if (!o.customer_id || !o.closed_at) continue;
    const local = DateTime.fromISO(o.closed_at).setZone(tzByLocation.get(o.location_id) || settings.timezone);
    const date = local.toISODate();
    const items = (o.line_items ?? [])
      .filter((li) => li.name && li.item_type !== 'CUSTOM_AMOUNT')
      .map((li) => ({ name: li.name.trim(), qty: parseFloat(li.quantity) || 1 }));
    const guest = visitsByGuest.get(o.customer_id) ?? new Map();
    const v = guest.get(date) ?? { date, weekday: WEEKDAYS[local.weekday - 1], daypart: daypart(local.hour), type: orderType(o), total: 0, items: [] };
    v.total += money(o.total_money);
    v.items.push(...items);
    guest.set(date, v);
    visitsByGuest.set(o.customer_id, guest);
  }
}

// ---------- Customer profiles from Square
const profiles = new Map();
for (const page of $('Get Guest Profiles').all()) {
  for (const [id, r] of Object.entries(page.json.responses ?? {})) {
    if (r?.customer) profiles.set(id, r.customer);
  }
}

const top = (counts, n) => [...counts.entries()].sort((a, b) => b[1] - a[1]).slice(0, n);
const median = (arr) => {
  if (!arr.length) return null;
  const s = [...arr].sort((a, b) => a - b);
  const m = Math.floor(s.length / 2);
  return s.length % 2 ? s[m] : (s[m - 1] + s[m]) / 2;
};

const guests = [];
for (const [id, byDay] of visitsByGuest) {
  const c = profiles.get(id);
  if (!c) continue;
  const visits = [...byDay.values()].sort((a, b) => a.date.localeCompare(b.date));
  const gaps = visits.slice(1).map((v, i) => DateTime.fromISO(v.date).diff(DateTime.fromISO(visits[i].date), 'days').days);
  const dishes = new Map();
  const parts = new Map();
  const days = new Map();
  const types = new Map();
  for (const v of visits) {
    for (const it of v.items) dishes.set(it.name, (dishes.get(it.name) ?? 0) + it.qty);
    parts.set(v.daypart, (parts.get(v.daypart) ?? 0) + 1);
    days.set(v.weekday, (days.get(v.weekday) ?? 0) + 1);
    types.set(v.type, (types.get(v.type) ?? 0) + 1);
  }
  const total = visits.reduce((s, v) => s + v.total, 0);
  guests.push({
    id,
    email: String(c.email_address ?? '').trim().toLowerCase(),
    first_name: String(c.given_name ?? '').trim(),
    birthday: String(c.birthday ?? ''),
    created_at: c.created_at ?? '',
    unsubscribed: c.preferences?.email_unsubscribed === true,
    visit_count: visits.length,
    first_visit: visits[0].date,
    last_visit: visits[visits.length - 1].date,
    median_gap_days: median(gaps),
    usual_daypart: top(parts, 1)[0]?.[0] ?? '',
    usual_days: top(days, 2).map(([d]) => d),
    usual_type: top(types, 1)[0]?.[0] ?? 'dine-in',
    share: {
      weeknight_dinner: visits.filter((v) => v.daypart === 'dinner' && ['Monday', 'Tuesday', 'Wednesday', 'Thursday'].includes(v.weekday)).length / visits.length,
      weekend: visits.filter((v) => ['Friday', 'Saturday', 'Sunday'].includes(v.weekday)).length / visits.length,
      lunch: visits.filter((v) => v.daypart === 'lunch').length / visits.length,
      takeout: visits.filter((v) => v.type !== 'dine-in').length / visits.length,
    },
    favorite_dishes: top(dishes, 3).map(([name, count]) => ({ name, count })),
    avg_check: Math.round((total / visits.length) * 100) / 100,
    total_spent: Math.round(total * 100) / 100,
    visits: visits.map((v) => ({ date: v.date, weekday: v.weekday, daypart: v.daypart, type: v.type, total: Math.round(v.total * 100) / 100 })),
  });
}

// ---------- Menu (active items with their first price)
const menu = [];
for (const page of $('Get Menu').all()) {
  for (const item of page.json.items ?? []) {
    const d = item.item_data ?? {};
    if (!d.name || d.is_archived) continue;
    const price = d.variations?.map((v) => v.item_variation_data?.price_money).find((m) => m && m.amount !== undefined);
    menu.push({
      name: d.name.trim(),
      price: price ? Number(price.amount) / 100 : null,
      currency: price?.currency ?? 'USD',
      description: String(d.description_plaintext ?? d.description ?? '').trim().slice(0, 160),
    });
  }
}

return [{ json: { guests, menu, guest_count: guests.length, menu_count: menu.length } }];

// GUEST EMAIL PLAYBOOK: who gets which email, and what each email should do. Edit to match your restaurant.
// Each guest gets at most one email per run, in this order of priority: birthday, thank_you, we_miss_you, welcome.
const PLAYBOOK = {
  birthday: {
    name: 'Birthday',
    goal: 'Wish them a happy birthday and invite them in to celebrate.',
    instructions: 'Warm and personal. Mention a favorite dish if they have one. If there is a birthday offer, mention it once in the body.',
    link: 'their usual way to visit: reservations for dine-in guests, online ordering for takeout and delivery guests',
  },
  thank_you: {
    name: 'Thank you for your first visit',
    goal: 'Thank a first-time guest and ask for a Google review.',
    instructions: 'Thank them for coming in, mention what they ordered, and ask for an honest Google review in one sentence. Do not offer anything in exchange for a review.',
    link: 'your Google review page',
  },
  we_miss_you: {
    name: 'We miss you',
    goal: 'Bring back a regular who is overdue for a visit.',
    instructions: 'Notice that it has been a while without guilt-tripping. Mention their favorite dish by name and something on the menu they have not tried. If there is a we-miss-you offer, mention it once.',
    link: 'their usual way to visit: reservations for dine-in guests, online ordering for takeout and delivery guests',
  },
  welcome: {
    name: 'Welcome',
    goal: 'Welcome a new guest who just joined and invite them for a first visit.',
    instructions: 'Say what the restaurant is known for and recommend 2 or 3 of the most popular dishes.',
    link: 'reservations, or the website if there is no reservations link',
  },
};

const s = $('Settings').first().json;
const { guests } = $('Build Guest Stats').first().json;
const newGuests = $('Find New Guests').first().json.customers ?? [];
const today = $now.setZone(s.timezone).startOf('day');
const yesterday = today.minus({ days: 1 }).toISODate();
const daysSince = (date) => Math.round(today.diff(DateTime.fromISO(date, { zone: s.timezone }).startOf('day'), 'days').days);
const validEmail = (e) => /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(e);

// Days until the next birthday (Square stores YYYY-MM-DD or MM-DD)
const daysToBirthday = (b) => {
  const m = String(b).match(/(\d{2})-(\d{2})$/);
  if (!m) return null;
  let next = DateTime.fromObject({ year: today.year, month: Number(m[1]), day: Number(m[2]) }, { zone: s.timezone });
  if (!next.isValid) return null;
  if (next < today) next = next.plus({ years: 1 });
  return Math.round(next.diff(today, 'days').days);
};

const linkFor = (type, usualType) => {
  if (type === 'thank_you') return s.google_review_url || s.website_url;
  if (type === 'welcome') return s.reservation_url || s.website_url;
  return (usualType === 'dine-in' ? s.reservation_url : s.order_online_url) || s.website_url;
};
const offerFor = (type) => (type === 'birthday' ? s.birthday_offer : type === 'we_miss_you' ? s.we_miss_you_offer : '') || '';

const candidates = [];
const seen = new Set();
for (const g of guests) {
  if (!validEmail(g.email) || g.unsubscribed || seen.has(g.email)) continue;
  const toBirthday = daysToBirthday(g.birthday);
  const since = daysSince(g.last_visit);
  const isNew = g.created_at && DateTime.fromISO(g.created_at) >= today.minus({ days: 30 });
  const overdueAfter = Math.max(Number(s.lapsed_after_days) || 30, Math.ceil(2 * (g.median_gap_days ?? 15)));

  let type = null;
  if (toBirthday !== null && toBirthday <= 7) type = 'birthday';
  else if (g.visit_count === 1 && g.last_visit === yesterday && isNew) type = 'thank_you';
  else if (g.visit_count >= 3 && since >= overdueAfter) type = 'we_miss_you';
  if (!type) continue;
  seen.add(g.email);
  candidates.push({ g, type, since, toBirthday, overdueAfter });
}

// New sign-ups from the last day who haven't ordered yet (guests who already ordered get the thank-you email tomorrow)
const ordered = new Set(guests.map((g) => g.id));
for (const c of newGuests) {
  const email = String(c.email_address ?? '').trim().toLowerCase();
  if (!validEmail(email) || c.preferences?.email_unsubscribed === true || seen.has(email) || ordered.has(c.id)) continue;
  seen.add(email);
  candidates.push({
    g: { id: c.id, email, first_name: String(c.given_name ?? '').trim(), visit_count: 0, favorite_dishes: [], usual_type: 'dine-in', total_spent: 0 },
    type: 'welcome',
  });
}

const order = ['birthday', 'thank_you', 'we_miss_you', 'welcome'];
candidates.sort((a, b) => order.indexOf(a.type) - order.indexOf(b.type) || (b.g.total_spent ?? 0) - (a.g.total_spent ?? 0));

// Up to 3 times the daily cap, because some will be filtered out by Mailchimp status and cooldown
const cap = (Number(s.max_emails_per_run) || 40) * 3;

return candidates.slice(0, cap).map(({ g, type, since, toBirthday, overdueAfter }, i) => {
  const p = PLAYBOOK[type];
  const lines = [
    `First name: ${g.first_name || 'unknown (do not use a name)'}`,
    g.visit_count
      ? `Visits in the last ${s.history_days} days: ${g.visit_count} (first ${g.first_visit}, last ${g.last_visit}, ${since} days ago)`
      : 'Has not visited yet (just joined).',
  ];
  if (g.visit_count) {
    lines.push(`Usually comes for ${g.usual_daypart} on ${g.usual_days.join(' and ')}, mostly ${g.usual_type}. Average check ${g.avg_check}.`);
    if (g.median_gap_days) lines.push(`Usually comes back every ${Math.round(g.median_gap_days)} days.`);
  }
  if (g.favorite_dishes?.length) lines.push(`Favorite dishes: ${g.favorite_dishes.map((d) => `${d.name} (${d.count}x)`).join('; ')}`);
  if (type === 'birthday') lines.push(toBirthday === 0 ? 'Their birthday is today.' : `Their birthday is in ${toBirthday} days.`);
  if (type === 'we_miss_you') lines.push(`Overdue: we expected them back after about ${overdueAfter} days.`);

  return {
    json: {
      email: g.email,
      first_name: g.first_name,
      email_type: type,
      email_name: p.name,
      goal: p.goal,
      instructions: p.instructions,
      link_description: p.link,
      cta_url: linkFor(type, g.usual_type),
      offer: offerFor(type),
      last_visit: g.last_visit ?? '',
      guest_brief: lines.join('\n'),
      // Kept for the optional Width.ai send-time prediction
      square_customer_id: g.id,
      visit_history: g.visits ?? [],
    },
    pairedItem: { item: 0 },
  };
});

// Keeps only guests who are subscribed in Mailchimp and haven't had an AI email too recently.
// Mailchimp is the source of marketing consent; Square only supplies the visit history.
const s = $('Settings').first().json;
const candidates = $('Pick Guests to Email').all();
const today = $now.setZone(s.timezone).startOf('day');
const cooldown = Number(s.cooldown_days) || 14;
const cap = Number(s.max_emails_per_run) || 40;

const out = [];
$input.all().forEach((item, i) => {
  if (out.length >= cap) return;
  const guest = candidates[i]?.json;
  const member = item.json;
  if (!guest || member.status !== 'subscribed') return;

  const lastSent = String(member.merge_fields?.AI_SENT ?? '').trim();
  const lastType = String(member.merge_fields?.AI_TYPE ?? '').trim();
  if (/^\d{4}-\d{2}-\d{2}$/.test(lastSent)) {
    const days = Math.round(today.diff(DateTime.fromISO(lastSent, { zone: s.timezone }), 'days').days);
    // One AI email per guest per cooldown period
    if (days < cooldown) return;
    // One birthday email a year
    if (guest.email_type === 'birthday' && lastType === 'birthday' && days < 300) return;
    // A second "we miss you" only after they have come back since the last one
    if (guest.email_type === 'we_miss_you' && lastType === 'we_miss_you' && lastSent >= guest.last_visit) return;
  }
  out.push({ json: guest, pairedItem: { item: i } });
});

return out;

