// Checks the agent's email and turns it into Mailchimp audience fields (each up to 255 characters).
// Dishes are only included if they match an item on your Square menu, with its real price.
const s = $('Settings').first().json;
const guest = $('Keep Subscribed Guests').item.json;
const ai = $json.output ?? {};
const menu = $('Build Guest Stats').first().json.menu;

// Plain text only: no HTML, and no *| |* that Mailchimp would read as a merge tag
const clean = (v, max = 255) => String(v ?? '')
  .replace(/<[^>]*>/g, '')
  .replace(/\*\||\|\*/g, '')
  .replace(/\s+/g, ' ')
  .trim()
  .slice(0, max);
const price = (d) => {
  if (d.price === null) return '';
  try {
    return new Intl.NumberFormat('en-US', { style: 'currency', currency: d.currency || 'USD' }).format(d.price);
  } catch (e) {
    return d.price.toFixed(2);
  }
};

const byName = new Map(menu.map((d) => [d.name.toLowerCase(), d]));
const dishes = (Array.isArray(ai.featured_dishes) ? ai.featured_dishes : [])
  .map((n) => byName.get(String(n).trim().toLowerCase()))
  .filter(Boolean)
  .slice(0, 3)
  .map((d) => (price(d) ? `${d.name} (${price(d)})` : d.name));

const fallback = {
  birthday: 'Happy birthday from all of us',
  thank_you: 'Thanks for coming in',
  we_miss_you: 'It has been a while',
  welcome: `Welcome to ${s.restaurant_name}`,
}[guest.email_type];

return {
  json: {
    email: guest.email,
    email_type: guest.email_type,
    merge_fields: {
      AI_SUBJECT: clean(ai.subject, 150) || fallback,
      AI_PREVIEW: clean(ai.preview_text, 150),
      AI_HEAD: clean(ai.headline, 150) || fallback,
      AI_BODY1: clean(ai.body_1),
      AI_BODY2: clean(ai.body_2),
      AI_DISHES: dishes.join(' · ').slice(0, 255),
      AI_CTA: clean(ai.cta_text, 40) || 'Visit us',
      AI_LINK: guest.cta_url,
      AI_OFFER: clean(guest.offer),
      AI_TYPE: guest.email_type,
      AI_SENT: $now.setZone(s.timezone).toISODate(),
    },
    ai_reasoning: clean(ai.reasoning, 300),
  },
};

// Used when the AI agent fails: fills the same Mailchimp fields with simple copy for the email type,
// so the guest still gets a friendly email.
const s = $('Settings').first().json;
const guest = $('Keep Subscribed Guests').item.json;
const name = s.restaurant_name;
const COPY = {
  birthday: ['Happy birthday from all of us', `Happy birthday from everyone at ${name}. We would love to help you celebrate.`, 'Book a table'],
  thank_you: ['Thanks for coming in', `Thank you for visiting ${name}. If you enjoyed it, a quick Google review helps us a lot.`, 'Leave a review'],
  we_miss_you: ['It has been a while', `We have missed you at ${name}. Come back and see what is on the menu this week.`, 'Plan a visit'],
  welcome: [`Welcome to ${name}`, `Thanks for joining us. We look forward to cooking for you soon.`, 'Plan a visit'],
}[guest.email_type];

return {
  json: {
    email: guest.email,
    email_type: guest.email_type,
    merge_fields: {
      AI_SUBJECT: COPY[0],
      AI_PREVIEW: '',
      AI_HEAD: COPY[0],
      AI_BODY1: COPY[1],
      AI_BODY2: '',
      AI_DISHES: '',
      AI_CTA: COPY[2],
      AI_LINK: guest.cta_url,
      AI_OFFER: String(guest.offer ?? '').slice(0, 255),
      AI_TYPE: guest.email_type,
      AI_SENT: $now.setZone(s.timezone).toISODate(),
    },
    ai_reasoning: `The AI agent failed, so fallback copy was used: ${String($json.error?.message ?? $json.error ?? 'unknown error').slice(0, 200)}`,
  },
};

// Reads the campaign request from the form, or uses the weekly brief from Settings for the weekly run.
const settings = $('Settings').first().json;
const form = $('Campaign Request Form').isExecuted ? $('Campaign Request Form').first().json : null;
const text = (v, max = 1000) => String(v ?? '').trim().slice(0, max);

return [{
  json: {
    source: form ? 'form' : 'weekly planner',
    brief: form ? text(form.brief, 2000) : text(settings.weekly_brief, 2000),
    focus: form ? text(form.focus) : '',
    audience: form ? text(form.audience) : '',
    offer: form ? text(form.offer, 255) : '',
  },
}];

// Builds the Campaign Strategist Agent's brief from Square and Mailchimp:
// the slowest and busiest shifts, dish trends, guest groups it can send to, and past campaign results.
const s = $('Settings').first().json;
const req = $('Read Campaign Request').first().json;
const { guests, menu } = $('Build Guest Stats').first().json;
const today = $now.setZone(s.timezone).startOf('day');
const WEEKDAYS = ['Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday', 'Sunday'];
const tzByLocation = new Map((($('Get Square Locations').first().json.locations) ?? []).map((l) => [l.id, l.timezone || s.timezone]));
const money = (m) => (m && Number.isFinite(Number(m.amount)) ? Number(m.amount) / 100 : 0);
const pct = (v) => `${(Number(v || 0) * 100).toFixed(1)}%`;

// ---------- Shifts (weekday x lunch/dinner) over the last 8 weeks, and dish sales by 4-week period
const start8w = today.minus({ weeks: 8 });
const start4w = today.minus({ weeks: 4 });
const shifts = new Map();
const recent = new Map();
const prior = new Map();
for (const page of $('Get Square Orders').all()) {
  for (const o of page.json.orders ?? []) {
    if (!o.closed_at) continue;
    const t = DateTime.fromISO(o.closed_at).setZone(tzByLocation.get(o.location_id) || s.timezone);
    if (t < start8w || t >= today) continue;
    const part = t.hour >= 11 && t.hour < 16 ? 'lunch' : t.hour >= 16 && t.hour < 22 ? 'dinner' : null;
    if (part) {
      const key = `${WEEKDAYS[t.weekday - 1]} ${part}`;
      const sh = shifts.get(key) ?? { key, orders: 0, sales: 0 };
      sh.orders += 1;
      sh.sales += money(o.total_money);
      shifts.set(key, sh);
    }
    const bucket = t >= start4w ? recent : prior;
    for (const li of o.line_items ?? []) {
      if (!li.name || li.item_type === 'CUSTOM_AMOUNT') continue;
      bucket.set(li.name.trim(), (bucket.get(li.name.trim()) ?? 0) + (parseFloat(li.quantity) || 1));
    }
  }
}
// Average per shift (8 of each weekday in 8 weeks); shifts under 10% of the busiest are treated as closed
const shiftList = [...shifts.values()].map((sh) => ({ ...sh, avg_orders: sh.orders / 8, avg_sales: sh.sales / 8 }));
const busiest = Math.max(0, ...shiftList.map((x) => x.avg_orders));
const open = shiftList.filter((x) => x.avg_orders >= busiest * 0.1).sort((a, b) => a.avg_sales - b.avg_sales);
const shiftLine = (x) => `${x.key} | ${x.avg_orders.toFixed(1)} orders | ${x.avg_sales.toFixed(0)} in sales`;

const onMenu = new Map(menu.map((d) => [d.name.toLowerCase(), d]));
const dishLine = (name, extra) => {
  const d = onMenu.get(name.toLowerCase());
  return `${name}${d?.price !== null && d?.price !== undefined ? ` | ${d.price.toFixed(2)} ${d.currency}` : ''} | ${extra}`;
};
const topSellers = [...recent.entries()].filter(([n]) => onMenu.has(n.toLowerCase())).sort((a, b) => b[1] - a[1]).slice(0, 10);
const rising = [...recent.entries()]
  .filter(([n, q]) => onMenu.has(n.toLowerCase()) && q >= 5 && (prior.get(n) ?? 0) > 0 && q >= (prior.get(n) ?? 0) * 1.3)
  .sort((a, b) => b[1] / (prior.get(b[0]) || 1) - a[1] / (prior.get(a[0]) || 1)).slice(0, 5);
const newDishes = [...recent.entries()].filter(([n, q]) => onMenu.has(n.toLowerCase()) && q >= 3 && !prior.has(n)).slice(0, 5);

// ---------- Guest groups from Square (only guests with an email who haven't unsubscribed in Square)
const reachable = guests.filter((g) => /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(g.email) && !g.unsubscribed);
const since = (g) => Math.round(today.diff(DateTime.fromISO(g.last_visit, { zone: s.timezone }), 'days').days);
const checks = [...reachable].filter((g) => g.visit_count >= 2).map((g) => g.avg_check).sort((a, b) => b - a);
const bigSpend = checks.length ? checks[Math.max(0, Math.ceil(checks.length * 0.2) - 1)] : Infinity;
const GROUPS = [
  ['all_guests', 'All guests', 'Every guest with an email from the last history window', () => true],
  ['regulars', 'Regulars', '3 or more visits, and visited in the last 30 days', (g) => g.visit_count >= 3 && since(g) <= 30],
  ['lapsed', 'Lapsed guests', '2 or more visits, but none in the last 45 days', (g) => g.visit_count >= 2 && since(g) > 45],
  ['weeknight_diners', 'Weeknight diners', 'At least half their visits are Monday to Thursday dinner', (g) => g.visit_count >= 2 && g.share.weeknight_dinner >= 0.5],
  ['weekend_guests', 'Weekend guests', 'At least half their visits are Friday to Sunday', (g) => g.visit_count >= 2 && g.share.weekend >= 0.5],
  ['lunch_guests', 'Lunch guests', 'At least half their visits are at lunch', (g) => g.visit_count >= 2 && g.share.lunch >= 0.5],
  ['takeout_guests', 'Takeout and delivery guests', 'At least half their orders are takeout or delivery', (g) => g.share.takeout >= 0.5],
  ['new_guests', 'New guests', 'First visit in the last 30 days', (g) => DateTime.fromISO(g.first_visit, { zone: s.timezone }) >= today.minus({ days: 30 })],
  ['big_spenders', 'Big spenders', 'Top 20% by average check, with 2 or more visits', (g) => g.visit_count >= 2 && g.avg_check >= bigSpend],
];
const groups = GROUPS.map(([key, label, description, test]) => {
  const emails = [...new Set(reachable.filter(test).map((g) => g.email))];
  return { key, label, description, count: emails.length, emails };
});

// ---------- Past Mailchimp campaigns for this audience
const reports = ($('Get Mailchimp Reports').first().json.reports ?? [])
  .filter((r) => r.list_id === s.mailchimp_list_id && r.emails_sent > 0)
  .sort((a, b) => String(b.send_time).localeCompare(String(a.send_time)))
  .slice(0, 10)
  .map((r) => {
    const sent = r.send_time ? DateTime.fromISO(r.send_time).setZone(s.timezone) : null;
    return `${r.campaign_title || r.subject_line} | "${r.subject_line}" | sent ${sent ? sent.toFormat('ccc LLL d, h:mm a') : 'unknown'} | ${r.emails_sent} sent | opens ${pct(r.opens?.open_rate)} | clicks ${pct(r.clicks?.click_rate)}`;
  });

const section = (title, rows, empty) => `${title}\n${rows.length ? rows.join('\n') : empty}`;
const prompt = [
  'CAMPAIGN REQUEST',
  `Source: ${req.source}`,
  `Brief: ${req.brief}`,
  `Dishes or theme to feature: ${req.focus || 'your choice, based on the data'}`,
  `Audience wanted: ${req.audience || 'your choice, from the guest groups below'}`,
  `Offer to include: ${req.offer || 'none. Do not offer a discount or deal.'}`,
  `Today: ${today.toFormat('cccc, yyyy-MM-dd')} (${s.timezone})`,
  '',
  section('SLOWEST OPEN SHIFTS, LAST 8 WEEKS (shift | average orders | average sales)', open.slice(0, 4).map(shiftLine), 'Not enough order data.'),
  section('BUSIEST SHIFTS', [...open].reverse().slice(0, 3).map(shiftLine), 'Not enough order data.'),
  '',
  section('TOP DISHES, LAST 4 WEEKS (dish | price | sold)', topSellers.map(([n, q]) => dishLine(n, `${q} sold`)), 'none'),
  section('RISING DISHES (sold 30% more than the 4 weeks before)', rising.map(([n, q]) => dishLine(n, `${q} sold, up from ${prior.get(n)}`)), 'none'),
  section('NEW DISHES (first sold in the last 4 weeks)', newDishes.map(([n, q]) => dishLine(n, `${q} sold`)), 'none'),
  `Full menu: ${menu.length} items. Use Search_Menu to look up any dish.`,
  '',
  section('GUEST GROUPS FROM SQUARE (key | name | guests with email | who)', groups.map((g) => `${g.key} | ${g.label} | ${g.count} | ${g.description}`), 'none'),
  '',
  section('PAST MAILCHIMP CAMPAIGNS (title | subject | sent | emails | open rate | click rate)', reports, 'No past campaigns found.'),
].join('\n');

return [{ json: { revision: 0, prompt, original_prompt: prompt, groups, request: req } }];

