parameters.jsCode:
// Checks the agent's campaign and builds the Mailchimp email: the audience from Square,
// dishes matched to the Square menu with real prices, and the HTML with Mailchimp's merge tags.
const s = $('Settings').first().json;
const ctx = $('Build Campaign Context').first().json;
const { menu } = $('Build Guest Stats').first().json;
const ai = $json.output ?? {};
const revision = $('Prepare Revision').isExecuted ? $('Prepare Revision').first().json.revision : 0;
const tz = s.timezone;

// Plain text only: no HTML, and no *| |* that Mailchimp would read as a merge tag
const clean = (v, max) => String(v ?? '').replace(/<[^>]*>/g, '').replace(/\*\||\|\*/g, '').replace(/\s+/g, ' ').trim().slice(0, max);
const esc = (v) => String(v ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');

const group = ctx.groups.find((g) => g.key === String(ai.audience ?? '').trim());
if (!group) throw new Error(`The agent chose the audience "${ai.audience}", which is not one of the guest groups. Run the campaign again.`);
if (!group.count) throw new Error(`The "${group.label}" group has no guests with an email. Run the campaign again with another audience.`);

const subject = clean(ai.subject, 150);
if (!subject) throw new Error('The agent did not return a subject line. Run the campaign again.');

const byName = new Map(menu.map((d) => [d.name.toLowerCase(), d]));
const price = (d) => {
  if (d.price === null) return '';
  try {
    return new Intl.NumberFormat('en-US', { style: 'currency', currency: d.currency || 'USD' }).format(d.price);
  } catch (e) {
    return d.price.toFixed(2);
  }
};
const dishes = (Array.isArray(ai.featured_dishes) ? ai.featured_dishes : [])
  .map((n) => byName.get(String(n).trim().toLowerCase()))
  .filter(Boolean)
  .filter((d, i, all) => all.indexOf(d) === i)
  .slice(0, 4);

const links = { reserve: s.reservation_url, order: s.order_online_url, website: s.website_url };
const ctaUrl = links[ai.cta] || s.reservation_url || s.order_online_url || s.website_url;
const ctaText = clean(ai.cta_text, 30) || (ai.cta === 'order' ? 'Order now' : ai.cta === 'reserve' ? 'Book a table' : 'Visit us');
const headline = clean(ai.headline, 90) || subject;
const intro = clean(ai.intro, 600);
const offer = clean(ai.offer_text, 255);
const sections = (Array.isArray(ai.sections) ? ai.sections : [])
  .map((x) => ({ heading: clean(x?.heading, 60), text: clean(x?.text, 500) }))
  .filter((x) => x.heading || x.text)
  .slice(0, 2);
const color = /^#[0-9a-f]{3,8}$/i.test(String(s.brand_color)) ? s.brand_color : '#7c2d12';

// The suggested send time, moved to the next quarter hour (Mailchimp only schedules on :00, :15, :30, :45)
let suggested = DateTime.fromFormat(String(ai.suggested_send_time ?? ''), 'yyyy-MM-dd HH:mm', { zone: tz });
if (suggested.isValid) {
  const extra = suggested.minute % 15;
  if (extra) suggested = suggested.plus({ minutes: 15 - extra }).set({ second: 0 });
  if (suggested < $now.plus({ minutes: 30 })) suggested = DateTime.invalid('past');
}

// ---------- Email HTML (table layout with inline styles, so it renders in every email client)
const font = 'font-family:Georgia,\'Times New Roman\',serif;';
const sans = 'font-family:Arial,Helvetica,sans-serif;';
const button = `<table role="presentation" cellpadding="0" cellspacing="0" style="margin:24px auto;"><tr><td style="background:${color};border-radius:4px;">`
  + `<a href="${esc(ctaUrl)}" style="display:inline-block;padding:14px 30px;${sans}font-size:16px;font-weight:bold;color:#ffffff;text-decoration:none;">${esc(ctaText)}</a></td></tr></table>`;
const header = s.logo_url
  ? `<img src="${esc(s.logo_url)}" alt="${esc(s.restaurant_name)}" width="160" style="display:block;margin:0 auto;max-width:160px;height:auto;border:0;">`
  : `<div style="${font}font-size:24px;text-align:center;color:${color};">${esc(s.restaurant_name)}</div>`;
const dishRows = dishes.map((d) => `<tr><td style="padding:12px 0;border-bottom:1px solid #e7e5e4;">`
  + `<div style="${font}font-size:18px;color:#1c1917;">${esc(d.name)}${price(d) ? `<span style="float:right;${sans}font-size:15px;color:#57534e;">${esc(price(d))}</span>` : ''}</div>`
  + (d.description ? `<div style="${sans}font-size:14px;line-height:1.5;color:#57534e;margin-top:4px;">${esc(d.description)}</div>` : '')
  + '</td></tr>').join('');

const html = `<!DOCTYPE html>
<html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>${esc(subject)}</title></head>
<body style="margin:0;padding:0;background:#f5f5f4;">
<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background:#f5f5f4;"><tr><td align="center" style="padding:24px 12px;">
<table role="presentation" width="600" cellpadding="0" cellspacing="0" style="width:100%;max-width:600px;background:#ffffff;border-radius:6px;">
<tr><td style="padding:28px 32px 8px;">${header}</td></tr>
<tr><td style="padding:16px 32px 0;">
<h1 style="${font}font-size:30px;line-height:1.2;font-weight:normal;color:#1c1917;margin:0 0 18px;text-align:center;">${esc(headline)}</h1>
<p style="${sans}font-size:16px;line-height:1.6;color:#44403c;margin:0 0 12px;">*|IF:FNAME|*Hi *|FNAME|*,*|ELSE:|*Hi there,*|END:IF|*</p>
${intro ? `<p style="${sans}font-size:16px;line-height:1.6;color:#44403c;margin:0 0 12px;">${esc(intro)}</p>` : ''}
${offer ? `<div style="${sans}font-size:16px;font-weight:bold;text-align:center;color:${color};border:2px solid ${color};border-radius:4px;padding:14px;margin:18px 0;">${esc(offer)}</div>` : ''}
${sections.map((x) => `${x.heading ? `<h2 style="${font}font-size:21px;font-weight:normal;color:#1c1917;margin:22px 0 8px;">${esc(x.heading)}</h2>` : ''}${x.text ? `<p style="${sans}font-size:16px;line-height:1.6;color:#44403c;margin:0 0 12px;">${esc(x.text)}</p>` : ''}`).join('\n')}
</td></tr>
${dishRows ? `<tr><td style="padding:8px 32px 0;"><table role="presentation" width="100%" cellpadding="0" cellspacing="0">${dishRows}</table></td></tr>` : ''}
<tr><td style="padding:0 32px 16px;">${button}</td></tr>
<tr><td style="padding:20px 32px 28px;border-top:1px solid #e7e5e4;${sans}font-size:12px;line-height:1.6;color:#78716c;text-align:center;">
*|LIST:COMPANY|*<br>*|HTML:LIST_ADDRESS_HTML|*<br>
<a href="*|UNSUB|*" style="color:#78716c;">Unsubscribe</a>
</td></tr>
</table>
</td></tr></table>
</body></html>`;

const date = $now.setZone(tz).toFormat('yyyy-MM-dd');
const campaignName = `${clean(ai.campaign_name, 80) || subject} (AI ${date}${revision ? `, v${revision + 1}` : ''})`;

return [{
  json: {
    revision,
    campaign_name: campaignName,
    tag_name: `AI campaign: ${campaignName}`.slice(0, 100),
    audience_key: group.key,
    audience_label: group.label,
    audience_count: group.count,
    emails: group.emails,
    subject,
    preview_text: clean(ai.preview_text, 150),
    headline,
    offer,
    dishes: dishes.map((d) => `${d.name}${price(d) ? ` (${price(d)})` : ''}`),
    cta_url: ctaUrl,
    suggested_send_time: suggested.isValid ? suggested.toFormat('yyyy-MM-dd HH:mm') : '',
    reasoning: clean(ai.reasoning, 600),
    html,
  },
}];

// Splits the audience into batches of 500, the most Mailchimp accepts per call when adding to a tag.
const email = $('Build Campaign Email').first().json;
const segmentId = $json.id;
if (!segmentId) {
  throw new Error(`Mailchimp did not create the audience tag: ${String($json.detail ?? $json.error?.message ?? JSON.stringify($json)).slice(0, 300)}`);
}

const out = [];
for (let i = 0; i < email.emails.length; i += 500) {
  out.push({ json: { segment_id: segmentId, members_to_add: email.emails.slice(i, i + 500) } });
}
return out;

// Builds the Slack message that asks for approval, with everything needed to decide.
const s = $('Settings').first().json;
const email = $('Build Campaign Email').first().json;
const campaign = $('Create Draft Campaign').first().json;
const recipients = $('Get Campaign Recipients').first().json;
const testSend = $('Send Test Email').first().json;
const req = $('Build Campaign Context').first().json.request;
const added = $('Add Guests to Tag').all().reduce((sum, i) => sum + (Number(i.json.total_added) || 0), 0);

if (!campaign?.id) {
  throw new Error(`Mailchimp did not create the draft campaign: ${String(campaign?.detail ?? campaign?.error?.message ?? JSON.stringify(campaign)).slice(0, 300)}`);
}
const count = recipients?.recipients?.recipient_count;
const testNote = testSend?.error || testSend?.status >= 400
  ? `The test email could not be sent (${String(testSend.detail ?? testSend.error?.message ?? testSend.error).slice(0, 120)}).`
  : `A test email was sent to ${s.approver_email}.`;

const lines = [
  `*New AI campaign draft${email.revision ? ` (version ${email.revision + 1})` : ''}* from the ${req.source}`,
  `*Campaign:* ${email.campaign_name}`,
  `*Audience:* ${email.audience_label} from Square: ${email.audience_count} guests with an email, ${added} found in Mailchimp${Number.isFinite(count) ? `, ${count} subscribed and will receive it` : ''}`,
  `*Subject:* ${email.subject}`,
  `*Preview text:* ${email.preview_text || '(none)'}`,
  `*Headline:* ${email.headline}`,
  email.offer ? `*Offer:* ${email.offer}` : '*Offer:* none',
  `*Dishes:* ${email.dishes.join(', ') || 'none'}`,
  `*Suggested send time:* ${email.suggested_send_time ? `${email.suggested_send_time} (${s.timezone})` : 'none'}`,
  `*Why:* ${email.reasoning}`,
  '',
  `${testNote} The draft is in Mailchimp under Campaigns, sent to the tag "${email.tag_name}".`,
];

return [{
  json: {
    campaign_id: campaign.id,
    segment_id: $('Create Audience Tag').first().json.id,
    recipient_count: Number.isFinite(count) ? count : null,
    slack_message: lines.join('\n').slice(0, 3500),
  },
}];

// Reads the reviewer's answer from Slack: send now, schedule, revise with notes, or keep as a draft.
// Mailchimp only schedules on the quarter hour, so times are moved to the next :00, :15, :30, or :45.
const s = $('Settings').first().json;
const approval = $('Build Approval Message').first().json;
const email = $('Build Campaign Email').first().json;
const answer = $json.data ?? null;
const maxRevisions = Number(s.max_revisions) || 3;

let decision = 'draft';
let note = 'No answer in Slack before the time limit, so the campaign was kept as a draft.';
let sendTime = '';
const choice = String(answer?.decision ?? '');
const notes = String(answer?.notes ?? '').trim().slice(0, 1500);

if (choice.startsWith('Send now')) {
  decision = 'send_now';
  note = '';
} else if (choice.startsWith('Schedule')) {
  const typed = String(answer?.send_time ?? '').trim();
  let when = DateTime.fromFormat(typed, 'yyyy-MM-dd HH:mm', { zone: s.timezone });
  if (!when.isValid) {
    note = `"${typed}" isn't a send time in the format 2026-11-12 16:00, so the campaign was kept as a draft.`;
  } else {
    const extra = when.minute % 15;
    if (extra) when = when.plus({ minutes: 15 - extra });
    if (when <= $now.plus({ minutes: 15 })) {
      note = `${typed} is less than 15 minutes away or in the past, so the campaign was kept as a draft.`;
    } else {
      decision = 'schedule';
      sendTime = when.toUTC().toISO({ suppressMilliseconds: true });
      note = `${when.toFormat('cccc, LLL d, yyyy, h:mm a')} (${s.timezone})`;
    }
  }
} else if (choice.startsWith('Revise')) {
  if (email.revision + 1 >= maxRevisions) {
    note = `This was version ${email.revision + 1} of ${maxRevisions}, so it was kept as a draft instead of being revised again.`;
  } else {
    decision = 'revise';
    note = notes || 'Try a different angle and subject line.';
  }
} else if (answer) {
  note = 'Kept as a draft in Mailchimp, as requested.';
}

return [{
  json: {
    decision,
    note,
    send_time: sendTime,
    feedback: decision === 'revise' ? note : '',
    campaign_id: approval.campaign_id,
    segment_id: approval.segment_id,
  },
}];

// Sends the campaign back to the agent with the reviewer's notes and the previous draft.
const ctx = $('Build Campaign Context').first().json;
const email = $('Build Campaign Email').first().json;
const decision = $('Read Decision').first().json;
const revision = email.revision + 1;

const previous = [
  `Audience: ${email.audience_label} (${email.audience_key})`,
  `Subject: ${email.subject}`,
  `Preview text: ${email.preview_text}`,
  `Headline: ${email.headline}`,
  `Offer: ${email.offer || 'none'}`,
  `Dishes: ${email.dishes.join('; ') || 'none'}`,
  `Suggested send time: ${email.suggested_send_time || 'none'}`,
].join('\n');

return [{
  json: {
    ...ctx,
    revision,
    prompt: `${ctx.original_prompt}\n\nREVISION ${revision}\nYour previous draft:\n${previous}\n\nFeedback from the reviewer: ${decision.feedback}\n\nWrite a new version of the campaign that follows this feedback. Keep what the reviewer did not ask to change.`,
  },
}];

// Writes the Slack confirmation: sent, scheduled, kept as a draft, or an error from Mailchimp.
const decision = $('Read Decision').first().json;
const email = $('Build Campaign Email').first().json;
const approval = $('Build Approval Message').first().json;
const res = $json;

const audience = `${email.audience_label}${approval.recipient_count !== null ? ` (${approval.recipient_count} subscribed guests)` : ''}`;
const failed = res.error || (Number(res.status) >= 400 && res.detail);
const error = failed ? String(res.detail ?? res.error?.message ?? res.error).slice(0, 300) : '';

let text;
if (decision.decision === 'send_now' && !error) {
  text = `:white_check_mark: *Sending now:* "${email.campaign_name}" to ${audience}.`;
} else if (decision.decision === 'schedule' && !error) {
  text = `:calendar: *Scheduled* for ${decision.note}: "${email.campaign_name}" to ${audience}.`;
} else if (error) {
  text = `:warning: Mailchimp returned an error, so "${email.campaign_name}" is still a draft in Mailchimp: ${error}`;
} else {
  text = `:memo: "${email.campaign_name}" is a draft in Mailchimp. ${decision.note}`;
}

return [{ json: { text } }];
